 count(a.rid) filter(where a.body_md5=e.old_md5 and (e.rid is null or a.rid=e.rid) and (e.kind='note' or a.label=e.old_label))::integer old_matches,
 jsonb_agg(jsonb_build_object('rid',a.rid,'md5',a.body_md5,'label',a.label)) filter(where a.rid is not null) actual
 from expected e left join actual a on a.kind=e.kind and a.eid=e.eid and a.slot=e.slot
 group by e.qid,e.kind,e.eid,e.slot,e.rid,e.new_md5,e.old_md5,e.new_label,e.old_label
), extras as (
 select a.kind,a.eid,a.slot,count(*) count from actual a
 where a.eid in (select distinct eid from expected) and not exists(select 1 from expected e where e.eid=a.eid and e.kind=a.kind and e.slot=a.slot)
 group by a.kind,a.eid,a.slot
)
select jsonb_build_object('batch','e21','expected_rows',(select count(*) from checked),'final_rows',(select count(*) from checked where matches=1 and final_matches=1),'old_rows',(select count(*) from checked where matches=1 and old_matches=1),'missing',(select count(*) from checked where matches=0),'duplicate_slots',(select count(*) from checked where matches>1),'mismatches',coalesce((select jsonb_agg(jsonb_build_object('qid',qid,'kind',kind,'slot',slot,'expected_id',rid,'expected_md5',new_md5,'matches',matches,'old_matches',old_matches,'actual',actual)) from checked where matches<>1 or final_matches<>1),'[]'::jsonb),'extra_slots',coalesce((select jsonb_agg(to_jsonb(extras)) from extras),'[]'::jsonb)) audit;
